<script setup lang="ts">
import type { ApiProblem } from '~/types/api'; import type { Course } from '~/types/domain'; import type { FormFieldDefinition } from '~/types/forms'
definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find, update } = useCourses(); const id = Number(route.params.id); const { data: course } = await useAsyncData(`course-edit-${id}`, () => find(id)); if (!course.value) throw createError({ statusCode: 404 })
const fields: FormFieldDefinition[] = [{ key: 'course_code', label: 'Course code', required: true }, { key: 'course_title', label: 'Course title', required: true }, { key: 'units', label: 'Units', type: 'number', required: true }, { key: 'description', label: 'Description' }, { key: 'status', label: 'Status', type: 'select', required: true, options: [{ label: 'Active', value: 'active' }, { label: 'Inactive', value: 'inactive' }] }]; const errors = ref<Record<string, string[]>>({}); const submitting = ref(false)
async function save(values: Record<string, string | number>) { submitting.value = true; try { await update(id, { ...values, units: Number(values.units) } as unknown as Partial<Course>); await navigateTo('/courses') } catch (error) { const problem = error as ApiProblem; errors.value = problem.errors ?? { form: [problem.message] } } finally { submitting.value = false } }
</script>
<template><div v-if="course" class="page-shell"><PageHeader title="Edit course" :description="course.course_title" /><EntityForm :fields="fields" :initial="{ course_code: course.course_code, course_title: course.course_title, units: course.units, description: course.description ?? '', status: course.status }" submit-label="Save changes" cancel-to="/courses" :submitting="submitting" :server-errors="errors" @submit="save" /></div></template>
